const FRAME = Color( 0.0941176, 0.129412, 0.164706, 1 )
const INNER = Color( 0.0352941, 0.0470588, 0.0627451, 1 )
const RIM = Color( 0.160784, 0.211765, 0.258824, 1 )
const RIM_FAINT = Color( 0.160784, 0.211765, 0.258824, 0.6 )
const BLOOD_DEEP = Color( 0.545098, 0.121569, 0.141176, 1 )
const BLOOD_TOP = Color( 0.784314, 0.243137, 0.258824, 1 )
const SHADOW = Color( 0.0352941, 0.0470588, 0.0627451, 0.3 )
const HILITE = Color( 0.894118, 0.913725, 0.937255, 0.1 )

var _flash := 0.0
var _last_amount := -1.0

func _process(delta):
				if _flash > 0.0:
								_flash -= delta
				var k = clamp(_flash / 0.12, 0.0, 1.0)
				modulate = Color(1, 1 - 0.10 * k, 1 - 0.14 * k, 1)

func _draw():
				var c = Vector2(80, 80)
				draw_circle(c, 80, FRAME)
				draw_circle(c, 74, INNER)
				draw_arc(c, 77, 0, TAU, 48, 3.0, RIM, true)
				draw_arc(c, 70, 0, TAU, 40, 1.0, RIM_FAINT, true)
				var pct = $TextureProgress.value / 100.0
				if pct > 0.005:
								var top = 80.0 - 66.0
								var h = 132.0 * pct
								var bands = 32
								var bh = h / bands
								for i in range(bands):
												var y0 = top + bh * i
												var yc = y0 + bh * 0.5
												var half = sqrt(max(0.0, 66.0 * 66.0 - (yc - 80.0) * (yc - 80.0)))
												var t = clamp((yc - top) / h, 0.0, 1.0)
												draw_rect(Rect2(80.0 - half, y0, half * 2.0, bh), BLOOD_DEEP.linear_interpolate(BLOOD_TOP, t))
				draw_arc(c, 66, PI, TAU, 24, 4.0, SHADOW, true)
				draw_arc(c, 62, PI * 1.12, PI * 1.38, 12, 2.0, HILITE, true)

func update_progress(amount, amount_max):
				var percent = amount / amount_max
				$TextureProgress.value = 100.0 * percent
				$HBoxContainer / HealthLabel.text = str(round(amount)) + " / " + str(round(amount_max))
				if amount < _last_amount:
								_flash = 0.12
				_last_amount = amount
				update()
